/* Fade and rise over the first 240px of scroll after the element's top enters the window (a
   fixed distance, so text in the first screen is already in place at load). Each step shifts
   the range by 40px, so a title, its paragraphs and its button arrive one after another. Only
   where the browser supports view timelines and the visitor allows motion. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .wild-ag-reveal {
      animation: wild-ag-reveal-in cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
      animation-timeline: view();
      animation-range: entry calc(var(--wild-ag-reveal-step, 0) * 40px) entry calc(240px + var(--wild-ag-reveal-step, 0) * 40px);
    }
  }
}

@keyframes wild-ag-reveal-in {
  from {
    opacity: 0;
    transform: translateY(var(--wild-ag-reveal-rise, 40px));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./wild-ag-reveal.css";

export interface WildAgRevealProps {
  children?: ReactNode;
  /** the element to render (div by default; p, li, h2… where it replaces one) */
  as?: ElementType;
  /** position in a staggered column: 0, 1, 2… each arrives a little later */
  step?: number;
  /** how far it rises, in px */
  rise?: number;
  className?: string;
}

export function WildAgReveal({ children, as: Tag = "div", step = 0, rise = 40, className }: WildAgRevealProps) {
  return (
    <Tag
      className={cn("wild-ag-reveal", className)}
      style={{ "--wild-ag-reveal-step": step, "--wild-ag-reveal-rise": `${rise}px` } as CSSProperties}
    >
      {children}
    </Tag>
  );
}
